import React, { useEffect, useState } from "react";

export default function StageView({
  stagedItems,
  setStagedItems,
  updateItem,
  insertItem,
  // ...other props
}) {
  const [showAsk, setShowAsk] = useState(true);
  const [editing, setEditing] = useState({ idx: null, field: null, value: "" });
  const chunkSize = 16;

  const totalItemCount = stagedItems.length;
  const chunks = [];
  for (let i = 0; i < stagedItems.length; i += chunkSize) {
    chunks.push(stagedItems.slice(i, i + chunkSize));
  }

  function beginEdit(idx, field, value) {
    setEditing({ idx, field, value });
  }

  function handleEditChange(e) {
    setEditing((cur) => ({ ...cur, value: e.target.value }));
  }

  async function handleEditCommit() {
    if (editing.idx == null || !editing.field) return;
    const newItems = [...stagedItems];
    let val = editing.value;
    if (editing.field === "unitPrice" && val !== "") val = Number(val).toFixed(2);
    if (editing.field === "count" && val !== "") val = parseInt(val, 10) || 0;
    newItems[editing.idx] = { ...newItems[editing.idx], [editing.field]: val };
    setStagedItems(newItems);
    if (updateItem) {
      const id = newItems[editing.idx]?.id;
      if (id) await updateItem(id, { [editing.field]: val });
    }
    setEditing({ idx: null, field: null, value: "" });
  }

  function handleKeyDown(e) {
    if (e.key === "Enter") handleEditCommit();
    if (e.key === "Escape") setEditing({ idx: null, field: null, value: "" });
  }

  function handleBlur() {
    handleEditCommit();
  }

  function handleAskCountChange(id, value) {
    const askCount = parseInt(value, 10) || 0;
    setStagedItems(items =>
      items.map(item =>
        item.id === id ? { ...item, askCount } : item
      )
    );
  }

  function handleAskFocus(e) {
    if (e.target.value === "0") e.target.value = "";
  }

  function formatPrice(price) {
    if (price === "" || price === null || price === undefined) return "$0.00";
    const num = parseFloat(price);
    if (isNaN(num)) return "$0.00";
    return "$" + num.toFixed(2);
  }

  // Add new item with DB sync
  async function addItem() {
    const newItem = {
      section: "",
      product: "New Product",
      unitPrice: "0.00",
      count: 0,
      description: "",
      selected: true,
      askCount: 0,
    };
    if (insertItem) {
      const dbRecord = await insertItem(newItem);
      if (dbRecord) {
        setStagedItems([...stagedItems, dbRecord]);
      }
    }
  }

  return (
    <div className="table-responsive" style={{ paddingTop: "10px", paddingBottom: "120px" }}>
      <div className="mb-2 fw-bold">Total items: {totalItemCount}</div>
      <button
        className="btn btn-outline-dark mb-3 ms-2"
        onClick={() => setShowAsk((v) => !v)}
      >
        {showAsk ? "Hide Ask Column" : "Show Ask Column"}
      </button>
      <button className="btn btn-success mb-3 ms-2" onClick={addItem}>
        + Add Item
      </button>
      {chunks.map((chunk, pageIdx) => (
        <div key={pageIdx} style={{ marginTop: 50, marginBottom: 50, pageBreakAfter: "always" }}>
          <table
            className="table table-bordered table-striped text-center align-middle"
            style={{
              width: "100%",
              fontWeight: 700,
              borderCollapse: "collapse",
              tableLayout: "auto",
              background: "#fff",
              boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
            }}
          >
            <thead>
              <tr style={{ background: "#bababa" }}>
                <th style={{ width: showAsk ? "34%" : "44%" }}>Product</th>
                <th style={{ width: "18%" }}>Price</th>
                <th style={{ width: "18%" }}>Qty</th>
                {showAsk && <th style={{ width: "18%" }}>Ask</th>}
              </tr>
            </thead>
            <tbody>
              {chunk.map((item, idx) => {
                const globalIdx = pageIdx * chunkSize + idx;
                return (
                  <tr key={idx}>
                    <td
                      style={{
                        fontWeight: 700,
                        textAlign: "left",
                        whiteSpace: "pre-line",
                        wordBreak: "break-word",
                        overflowWrap: "break-word",
                        fontSize: "1.08rem",
                        cursor: "pointer",
                      }}
                      title={item.product}
                      onClick={() => beginEdit(globalIdx, "product", item.product)}
                    >
                      {editing.idx === globalIdx && editing.field === "product" ? (
                        <input
                          type="text"
                          className="form-control form-control-sm"
                          autoFocus
                          value={editing.value}
                          onChange={handleEditChange}
                          onBlur={handleBlur}
                          onKeyDown={handleKeyDown}
                          style={{
                            fontWeight: 700,
                            border: "2px solid #000",
                            boxShadow: "none",
                          }}
                        />
                      ) : (
                        item.product
                      )}
                    </td>
                    <td
                      style={{
                        fontWeight: 700,
                        cursor: "pointer",
                        verticalAlign: "middle",
                      }}
                      onClick={() => beginEdit(globalIdx, "unitPrice", item.unitPrice)}
                    >
                      {editing.idx === globalIdx && editing.field === "unitPrice" ? (
                        <input
                          type="number"
                          inputMode="decimal"
                          step="0.01"
                          className="form-control form-control-sm text-center"
                          autoFocus
                          value={editing.value}
                          onChange={handleEditChange}
                          onBlur={handleBlur}
                          onKeyDown={handleKeyDown}
                          style={{
                            fontWeight: 700,
                            border: "2px solid #000",
                            boxShadow: "none",
                          }}
                        />
                      ) : (
                        formatPrice(item.unitPrice)
                      )}
                    </td>
                    <td
                      style={{
                        fontWeight: 700,
                        cursor: "pointer",
                        verticalAlign: "middle",
                      }}
                      onClick={() => beginEdit(globalIdx, "count", item.count)}
                    >
                      {editing.idx === globalIdx && editing.field === "count" ? (
                        <input
                          type="number"
                          inputMode="numeric"
                          className="form-control form-control-sm text-center"
                          autoFocus
                          value={editing.value}
                          onChange={handleEditChange}
                          onBlur={handleBlur}
                          onKeyDown={handleKeyDown}
                          style={{
                            fontWeight: 700,
                            border: "2px solid #000",
                            boxShadow: "none",
                          }}
                        />
                      ) : (
                        item.count || ""
                      )}
                    </td>
                    {showAsk && (
                      <td style={{ fontWeight: 700 }}>
                        <input
                          type="number"
                          inputMode="numeric"
                          pattern="[0-9]*"
                          autoComplete="off"
                          className="form-control form-control-sm text-center"
                          style={{
                            maxWidth: 54,
                            fontWeight: 700,
                            border: "2px solid #000",
                            boxShadow: "none",
                          }}
                          min="0"
                          value={item.askCount ?? 0}
                          onChange={e => handleAskCountChange(item.id, e.target.value)}
                          onFocus={handleAskFocus}
                        />
                      </td>
                    )}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
}
